const shelf=document.querySelector('#album-shelf'),template=document.querySelector('#album-template'),viewer=document.querySelector('#viewer'),grid=document.querySelector('.viewer-grid'),menuButton=document.querySelector('.menu-toggle');
fetch('gallery-data.json').then(r=>r.json()).then(data=>{data.albums.forEach((album,index)=>{const card=template.content.cloneNode(true),button=card.querySelector('.album'),image=card.querySelector('img');image.src=album.cover;image.alt=`${album.title} album cover`;card.querySelector('.book strong').textContent=album.title;card.querySelector('.album-meta b').textContent=album.title;card.querySelector('.album-meta i').textContent=`${String(album.images.length).padStart(2,'0')} works`;button.style.setProperty('--i',index);button.addEventListener('click',()=>openAlbum(album));shelf.append(card)})}).catch(()=>{shelf.innerHTML='<p class="load-error">The archive is being prepared.</p>'});
function openAlbum(album){grid.innerHTML='';document.querySelector('.viewer-title').textContent=album.title;document.querySelector('.viewer-count').textContent=`${String(album.images.length).padStart(2,'0')} photographs`;album.images.forEach((src,i)=>{const figure=document.createElement('figure'),img=document.createElement('img');figure.className='work';img.src=src;img.alt=`${album.title}, photograph ${i+1}`;img.loading='lazy';figure.append(img);grid.append(figure)});viewer.classList.add('is-open');viewer.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';document.querySelector('.back').focus()}
function closeAlbum(){viewer.classList.remove('is-open');viewer.setAttribute('aria-hidden','true');document.body.style.overflow=''}document.querySelector('.back').addEventListener('click',closeAlbum);
let drag=false,start=0,left=0;shelf.addEventListener('pointerdown',e=>{if(e.target.closest('.album'))return;drag=true;start=e.clientX;left=shelf.scrollLeft;shelf.setPointerCapture(e.pointerId)});shelf.addEventListener('pointermove',e=>{if(drag)shelf.scrollLeft=left-(e.clientX-start)});shelf.addEventListener('pointerup',()=>drag=false);
function toggleMenu(force){const open=force??!document.documentElement.classList.contains('menu-open');document.documentElement.classList.toggle('menu-open',open);menuButton.setAttribute('aria-expanded',open);menuButton.setAttribute('aria-label',open?'Close menu':'Open menu');document.querySelector('.menu').setAttribute('aria-hidden',!open)}menuButton.addEventListener('click',()=>toggleMenu());
function closePanels(){document.querySelectorAll('.info-panel.is-open').forEach(panel=>{panel.classList.remove('is-open');panel.setAttribute('aria-hidden','true')});document.body.style.overflow=''}
function openPanel(id){closeAlbum();closePanels();if(id==='home'){toggleMenu(false);return}const panel=document.getElementById(id);panel.classList.add('is-open');panel.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';toggleMenu(false);panel.querySelector('.panel-close').focus()}
document.querySelectorAll('.menu-link').forEach(button=>button.addEventListener('click',()=>openPanel(button.dataset.target)));document.querySelectorAll('.panel-close').forEach(button=>button.addEventListener('click',closePanels));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeAlbum();closePanels();toggleMenu(false)}});
